/*
Embed the dial artwork (static/compass.svg, static/vr-watch.svg) as strings
in src/dial-art.ts, so the library draws them without a fetch. The SVG files
are the source of truth: edit them (Tonio draws them in AMDN), then run
`bun run dial-art`. The parts the code drives are found by id, so keep those
names when redrawing (see src/dials.ts).
*/
const ART: Record<string, string> = {
  compass: 'static/compass.svg',
  watch: 'static/vr-watch.svg',
}

let out =
  '// GENERATED by bin/dial-art.ts from ' +
  Object.values(ART).join(', ') +
  '. Do not edit: edit the SVGs and run `bun run dial-art`.\n\n'
for (const [name, path] of Object.entries(ART)) {
  const svg = (await Bun.file(path).text())
    .replace(/<\?xml[^>]*\?>\s*/, '')
    .replace(/<!--[\s\S]*?-->\s*/g, '')
    .trim()
  // In the shape prettier would give it, so `bun format` leaves it alone.
  const quoted =
    "'" +
    svg.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\r?\n/g, '\\n') +
    "'"
  out += `export const ${name}Svg =\n  ${quoted}\n`
}
await Bun.write('src/dial-art.ts', out)
console.log('wrote src/dial-art.ts')
